// AUTO-GENERATED by mercury-bridge pipeline.
// Vite plugin: rewrite CSS viewport units to Mercury virtual viewport variables.
// It also correlates deterministic source-edit jobs with the exact Vite HMR
// updates they caused. The edit runner opens a transaction over localhost
// before writing source and closes it with the accepted source file paths.
// Do not edit. Regenerated on every bridge install.

// Units that follow the Mercury virtual viewport rather than the real browser one.
const VIEWPORT_UNITS = new Set(['vh', 'dvh', 'svh', 'lvh', 'vw', 'dvw', 'svw', 'lvw'])
// A CSS number always ends in a digit, so a viewport length always has one immediately
// before its unit. The unit is a name and may be escaped ('100\76 h' and '100v\68' are
// both 100vh), but only after a literal prefix of a viewport unit. A cheap necessary
// condition, used only to skip tokenizing a stylesheet that cannot contain one.
const VIEWPORT_UNIT_HINT_RE = /\d(?:dvh|svh|lvh|vh|dvw|svw|lvw|vw|[dls]?v?\\)/i
// The <number> grammar, written once. Sticky, so it only ever matches at the cursor.
// Getting it exactly right is what makes '1.2.3vh' the number '1.2' followed by the
// dimension '.3vh' — two component values, an invalid declaration before and after any
// rewrite — rather than one malformed amount folded into 'calc(1.2.3 * …)'.
const CSS_NUMBER_RE = /[-+]?(?:\d*\.\d+|\d+)(?:[eE][-+]?\d+)?/y

// CSS token types (css-syntax-3 §4). Only the distinctions the classifier acts on get a
// name. Whitespace, comments and the legacy CDO/CDC markers are T_TRIVIA: they appear
// anywhere and never change how a statement is classified. Everything inert — numbers,
// percentages, hashes, commas, delimiters, and the whole body of a string or an
// unquoted url() — is T_OTHER, one span whose contents are never examined. A function
// token is 'ident(', which for structure is exactly an opening parenthesis.
const T_EOF = 0
const T_TRIVIA = 1
const T_OTHER = 2
const T_IDENT = 3
const T_AT_KEYWORD = 4
const T_DIMENSION = 5
const T_COLON = 6
const T_SEMICOLON = 7
const T_OPEN_PAREN = 8
const T_CLOSE_PAREN = 9
const T_OPEN_SQUARE = 10
const T_CLOSE_SQUARE = 11
const T_OPEN_CURLY = 12
const T_CLOSE_CURLY = 13
const EDIT_HMR_PATH = '/__mercury/edit-hmr-correlation'
const STAMP_VITE_REFRESH_PATH = '/__mercury/stamp-vite-refresh'
const EDIT_HMR_EVENT = 'mercury:edit-hmr-correlation'
const EDIT_HMR_QUIET_MS = 300
// Covers the repair agent's five-minute deadline plus final client verification.
const EDIT_HMR_MAX_LIFETIME_MS = 600000
const EDIT_HMR_FULL_RELOAD_HOLD_MS = 2_000
const EDIT_HMR_ID_RE = /^[a-zA-Z0-9_:-]{16,128}$/

type EditHmrTransaction = {
  seenFiles: Set<string>
  pendingUpdateFiles: Set<string>
  expectedFiles: Set<string> | null
  pendingFullReload: unknown | null
  fullReloadTimer: ReturnType<typeof setTimeout> | null
  quietTimer: ReturnType<typeof setTimeout> | null
  expiryTimer: ReturnType<typeof setTimeout>
}

type MercuryViteServer = {
  config: { root: string }
  middlewares: {
    use: (path: string, handler: (
      req: {
        method?: string
        socket?: { remoteAddress?: string }
        on: (event: string, listener: (chunk?: unknown) => void) => void
      },
      res: { statusCode: number; end: (body?: string) => void },
      next: () => void,
    ) => void) => void
  }
  ws: { send: MercuryViteWsSend }
  watcher: { emit: (event: string, path: string) => void }
}

type MercuryViteWsSend = {
  (payload: unknown): void
  (event: string, data: unknown): void
}

const editHmrTransactions = new Map<string, EditHmrTransaction>()
let rawViteWsSend: MercuryViteWsSend | null = null
let editHmrMarkerSequence = 0

// Files whose next watcher 'change' was triggered by the stamp-refresh endpoint,
// not a real source edit. Kept OUT of open edit-HMR transactions: otherwise a
// stamp-originated event could be accepted as proof a direct edit's bytes
// reached Vite (the target_not_found repair path opens a transaction across the
// stamp), breaking the exact-update guarantee. Consumed on the first matching
// handleHotUpdate so a subsequent REAL edit of the same file still correlates;
// a bounded timer clears the marker if no update ever fires.
const STAMP_REFRESH_MARKER_TTL_MS = 10_000
const stampRefreshMarkers = new Map<string, ReturnType<typeof setTimeout>>()

function markStampRefreshPath(path: string): void {
  const existing = stampRefreshMarkers.get(path)
  if (existing) clearTimeout(existing)
  const timer = setTimeout(() => { stampRefreshMarkers.delete(path) }, STAMP_REFRESH_MARKER_TTL_MS)
  stampRefreshMarkers.set(path, timer)
}

// Returns true and consumes the marker when this change was stamp-originated.
function consumeStampRefreshPath(path: string): boolean {
  const timer = stampRefreshMarkers.get(path)
  if (timer === undefined) return false
  clearTimeout(timer)
  stampRefreshMarkers.delete(path)
  return true
}

type EditHmrUpdateMarker = {
  verificationId: string
  files: string[]
}

function normalizeEditHmrPath(value: string): string {
  return value.replace(/\\/g, '/').replace(/\/{2,}/g, '/')
}

function absoluteEditHmrPath(server: MercuryViteServer, value: string): string {
  const normalized = normalizeEditHmrPath(value)
  if (normalized.startsWith('/')) return normalized
  return normalizeEditHmrPath(server.config.root + '/' + normalized)
}

function clearEditHmrTransaction(verificationId: string): void {
  const transaction = editHmrTransactions.get(verificationId)
  if (!transaction) return
  if (transaction.quietTimer) clearTimeout(transaction.quietTimer)
  if (transaction.fullReloadTimer) clearTimeout(transaction.fullReloadTimer)
  clearTimeout(transaction.expiryTimer)
  editHmrTransactions.delete(verificationId)
  // A failed/cancelled transaction must never strand a Vite full reload that
  // was briefly held while the backend determined which source writes landed.
  if (transaction.pendingFullReload && rawViteWsSend) {
    rawViteWsSend(transaction.pendingFullReload)
  }
}

function sendRawViteMessage(server: MercuryViteServer, payload: unknown): void {
  if (rawViteWsSend) rawViteWsSend(payload)
  else server.ws.send(payload)
}

function fullReloadChangedFile(
  server: MercuryViteServer,
  payload: unknown,
): string | null {
  if (!payload || typeof payload !== 'object' || (payload as { type?: unknown }).type !== 'full-reload') {
    return null
  }
  const triggeredBy = (payload as { triggeredBy?: unknown }).triggeredBy
  if (typeof triggeredBy === 'string' && triggeredBy.length > 0) {
    return absoluteEditHmrPath(server, triggeredBy)
  }
  const path = (payload as { path?: unknown }).path
  if (typeof path !== 'string' || path.length === 0 || path === '*') return null
  const relativePath = path.startsWith('/') ? path.slice(1) : path
  return normalizeEditHmrPath(server.config.root + '/' + relativePath)
}

function bufferCorrelatedFullReload(
  server: MercuryViteServer,
  payload: unknown,
): boolean {
  const changedFile = fullReloadChangedFile(server, payload)
  if (!changedFile) return false
  const matches = [...editHmrTransactions.entries()].filter(
    ([, transaction]) => transaction.seenFiles.has(changedFile),
  )
  // Project locking normally leaves exactly one transaction. Fail open on an
  // ambiguous match so this plugin can never suppress Vite's own reload.
  if (matches.length !== 1) return false
  const [verificationId, transaction] = matches[0]!
  transaction.pendingFullReload = payload
  if (transaction.fullReloadTimer) clearTimeout(transaction.fullReloadTimer)
  transaction.fullReloadTimer = setTimeout(() => {
    if (transaction.pendingFullReload !== payload) return
    transaction.pendingFullReload = null
    transaction.fullReloadTimer = null
    // Correlation is diagnostic. If the backend never finishes the edit
    // transaction, preserve Vite's normal reload behavior instead of holding
    // the preview until the longer transaction expiry.
    sendRawViteMessage(server, payload)
    clearEditHmrTransaction(verificationId)
  }, EDIT_HMR_FULL_RELOAD_HOLD_MS)
  if (transaction.quietTimer) {
    clearTimeout(transaction.quietTimer)
    transaction.quietTimer = null
  }
  return true
}

function takePendingEditHmrMarkers(): EditHmrUpdateMarker[] {
  const markers: EditHmrUpdateMarker[] = []
  for (const [verificationId, transaction] of editHmrTransactions) {
    if (transaction.pendingUpdateFiles.size === 0) continue
    markers.push({ verificationId, files: [...transaction.pendingUpdateFiles] })
    transaction.pendingUpdateFiles.clear()
  }
  return markers
}

function forwardCorrelatedVitePayload(
  server: MercuryViteServer,
  payload: unknown,
  send: MercuryViteWsSend,
): boolean {
  if (!payload || typeof payload !== 'object') return false
  const type = (payload as { type?: unknown }).type
  if (type !== 'update' && type !== 'error') return false
  const markers = takePendingEditHmrMarkers()
  if (markers.length > 0) {
    const markerId = 'mercury-hmr-' + Date.now().toString(36) + '-' + (++editHmrMarkerSequence).toString(36)
    // This marker and the Vite payload are adjacent messages on the same
    // ordered WebSocket. The bridge records the marker before Vite applies the
    // update. The update carries the same Mercury-owned batch id, so a later
    // unrelated afterUpdate cannot acknowledge a failed or missing batch.
    send({
      type: 'custom',
      event: EDIT_HMR_EVENT,
      data: {
        phase: type === 'update' ? 'before-update' : 'vite-error',
        ...(type === 'update' ? { markerId } : {}),
        markers,
      },
    })
    if (type === 'update') {
      // Vite currently forwards extension fields from the update payload to
      // vite:afterUpdate. If a future version strips this Mercury-owned ID,
      // verification expires as inconclusive instead of matching another HMR.
      send({
        ...(payload as Record<string, unknown>),
        mercuryEditHmrMarkerId: markerId,
      })
    } else {
      send(payload)
    }
  } else {
    send(payload)
  }
  for (const { verificationId } of markers) {
    maybePublishEditHmr(server, verificationId)
  }
  return true
}

function maybePublishEditHmr(server: MercuryViteServer, verificationId: string): void {
  const transaction = editHmrTransactions.get(verificationId)
  if (!transaction?.expectedFiles || transaction.expectedFiles.size === 0) return
  for (const file of transaction.expectedFiles) {
    if (!transaction.seenFiles.has(file)) return
  }
  if (transaction.pendingFullReload) {
    const fullReload = transaction.pendingFullReload
    transaction.pendingFullReload = null
    if (transaction.fullReloadTimer) {
      clearTimeout(transaction.fullReloadTimer)
      transaction.fullReloadTimer = null
    }
    // Send the exact edit token immediately before Vite's full-reload message.
    // The old document stores that token during vite:beforeFullReload and the
    // new bridge document consumes it after navigation.
    sendRawViteMessage(server, {
      type: 'custom',
      event: EDIT_HMR_EVENT,
      data: { phase: 'finish', verificationId, files: [], fullReload: true },
    })
    sendRawViteMessage(server, fullReload)
    clearEditHmrTransaction(verificationId)
    return
  }
  for (const file of transaction.expectedFiles) {
    if (transaction.pendingUpdateFiles.has(file)) return
  }
  if (transaction.quietTimer) clearTimeout(transaction.quietTimer)
  transaction.quietTimer = setTimeout(() => {
    if (editHmrTransactions.get(verificationId) !== transaction) return
    sendRawViteMessage(server, {
      type: 'custom',
      event: EDIT_HMR_EVENT,
      data: { phase: 'finish', verificationId, files: [...(transaction.expectedFiles ?? [])] },
    })
    clearEditHmrTransaction(verificationId)
  }, EDIT_HMR_QUIET_MS)
}

function beginEditHmrTransaction(verificationId: string): void {
  clearEditHmrTransaction(verificationId)
  const expiryTimer = setTimeout(() => {
    clearEditHmrTransaction(verificationId)
  }, EDIT_HMR_MAX_LIFETIME_MS)
  editHmrTransactions.set(verificationId, {
    seenFiles: new Set(),
    pendingUpdateFiles: new Set(),
    expectedFiles: null,
    pendingFullReload: null,
    fullReloadTimer: null,
    quietTimer: null,
    expiryTimer,
  })
}

function finishEditHmrTransaction(
  server: MercuryViteServer,
  verificationId: string,
  files: readonly string[],
): boolean {
  const transaction = editHmrTransactions.get(verificationId)
  if (!transaction) return false
  transaction.expectedFiles = new Set(files.map((file) => absoluteEditHmrPath(server, file)))
  if (transaction.expectedFiles.size === 0) {
    clearEditHmrTransaction(verificationId)
    return true
  }
  maybePublishEditHmr(server, verificationId)
  return true
}

function installEditHmrEndpoint(server: MercuryViteServer): void {
  server.middlewares.use(EDIT_HMR_PATH, (req, res, next) => {
    if (req.method !== 'POST') {
      next()
      return
    }
    const remoteAddress = req.socket?.remoteAddress ?? ''
    if (
      remoteAddress !== '127.0.0.1' &&
      remoteAddress !== '::1' &&
      remoteAddress !== '::ffff:127.0.0.1'
    ) {
      res.statusCode = 403
      res.end('localhost only')
      return
    }
    let body = ''
    let tooLarge = false
    req.on('data', (chunk) => {
      if (tooLarge) return
      body += typeof chunk === 'string' ? chunk : String(chunk ?? '')
      if (body.length > 64_000) tooLarge = true
    })
    req.on('end', () => {
      if (tooLarge) {
        res.statusCode = 413
        res.end('payload too large')
        return
      }
      try {
        const parsed = JSON.parse(body) as {
          action?: unknown
          verificationId?: unknown
          files?: unknown
        }
        const verificationId = typeof parsed.verificationId === 'string'
          ? parsed.verificationId
          : ''
        if (!EDIT_HMR_ID_RE.test(verificationId)) throw new Error('invalid verification id')
        if (parsed.action === 'begin') {
          beginEditHmrTransaction(verificationId)
        } else if (parsed.action === 'finish' && Array.isArray(parsed.files)) {
          const files = parsed.files.filter((file): file is string => (
            typeof file === 'string' &&
            file.length > 0 &&
            file.length <= 1_024 &&
            !normalizeEditHmrPath(file).split('/').includes('..')
          ))
          if (files.length !== parsed.files.length) throw new Error('invalid files')
          if (!finishEditHmrTransaction(server, verificationId, files)) {
            throw new Error('unknown verification id')
          }
        } else if (parsed.action === 'cancel') {
          clearEditHmrTransaction(verificationId)
        } else {
          throw new Error('invalid action')
        }
        res.statusCode = 204
        res.end()
      } catch {
        res.statusCode = 400
        res.end('invalid edit HMR correlation request')
      }
    })
  })
}

function installStampViteRefreshEndpoint(server: MercuryViteServer): void {
  server.middlewares.use(STAMP_VITE_REFRESH_PATH, (req, res, next) => {
    if (req.method !== 'POST') {
      next()
      return
    }
    const remoteAddress = req.socket?.remoteAddress ?? ''
    if (
      remoteAddress !== '127.0.0.1' &&
      remoteAddress !== '::1' &&
      remoteAddress !== '::ffff:127.0.0.1'
    ) {
      res.statusCode = 403
      res.end('localhost only')
      return
    }
    let body = ''
    let tooLarge = false
    req.on('data', (chunk) => {
      if (tooLarge) return
      body += typeof chunk === 'string' ? chunk : String(chunk ?? '')
      if (body.length > 256_000) tooLarge = true
    })
    req.on('end', () => {
      if (tooLarge) {
        res.statusCode = 413
        res.end('payload too large')
        return
      }
      try {
        const parsed = JSON.parse(body) as { files?: unknown }
        if (!Array.isArray(parsed.files)) throw new Error('invalid files')
        const files = parsed.files.filter((file): file is string => (
          typeof file === 'string' &&
          file.length > 0 &&
          file.length <= 1_024 &&
          !normalizeEditHmrPath(file).split('/').includes('..')
        ))
        if (files.length !== parsed.files.length) throw new Error('invalid files')
        // Re-emit a Vite watcher 'change' for each stamped file. This drives the
        // SAME pipeline a real filesystem event would (moduleGraph invalidation +
        // handleHotUpdate + HMR), so the client re-reads the stamped source — no
        // reliance on inotify actually delivering the E2B API write's event.
        // Mark each path first so handleHotUpdate keeps the stamp event out of
        // any open edit-HMR correlation.
        for (const file of files) {
          const abs = absoluteEditHmrPath(server, file)
          markStampRefreshPath(abs)
          server.watcher.emit('change', abs)
        }
        res.statusCode = 204
        res.end()
      } catch {
        res.statusCode = 400
        res.end('invalid stamp vite refresh request')
      }
    })
  })
}

// Statement position inside the innermost rule (or the stylesheet itself). Only a
// declaration's value may hold a length; a selector or at-rule prelude may not.
const MODE_STATEMENT = 0
const MODE_PRELUDE = 1
const MODE_VALUE = 2

type CssToken = { type: number; start: number; end: number; split: number }

type CssBlock = {
  // The token that closes this block. A closer that does not match the innermost
  // opener is an ordinary component value, exactly as the parser treats it.
  closer: number
  // True for a '{' that opens a rule or declaration list, false for '(', '[' and for
  // the '{' of a custom property's block value — inside those, ';' and '}' are
  // component values and the enclosing statement mode carries straight through.
  rule: boolean
  outerSkip: boolean
}

/**
 * A CSS tokenizer (css-syntax-3 §4), reduced to the token kinds that decide whether a
 * viewport dimension is a length.
 *
 * A regex cannot make that decision. Escapes rewrite identifier boundaries
 * ('\6b 100vh' is the single identifier 'k100vh'), spell url() any number of ways
 * ('u\72l(100vh)' is a url, not a function call), and hide structure inside selectors
 * ('.foo\{100vh\}'). Positions are reported against the original text so every byte
 * that is not a rewritten length survives untouched.
 */
function createCssTokenizer(css: string) {
  const token: CssToken = { type: T_EOF, start: 0, end: 0, split: 0 }
  let pos = 0

  const isNewline = (code: number): boolean => code === 0x0a || code === 0x0d || code === 0x0c
  const isSpace = (code: number): boolean => code === 0x20 || code === 0x09 || isNewline(code)
  const isDigit = (code: number): boolean => code >= 0x30 && code <= 0x39
  const isHex = (code: number): boolean =>
    isDigit(code) || (code >= 0x41 && code <= 0x46) || (code >= 0x61 && code <= 0x66)
  // Every non-ASCII code unit is a name code point, so 'k·100vh' and '💩100vh' are single
  // identifiers — and so is 'x␀100vh', since the parser preprocesses U+0000 into U+FFFD,
  // itself a name code point. NaN past the end of the string compares false throughout.
  const isNameStart = (code: number): boolean =>
    (code >= 0x41 && code <= 0x5a) || (code >= 0x61 && code <= 0x7a)
    || code === 0x5f || code >= 0x80 || code === 0
  const isName = (code: number): boolean => isNameStart(code) || isDigit(code) || code === 0x2d

  // A backslash escapes anything but a newline. At EOF it still escapes, matching the
  // parser's U+FFFD recovery, so a trailing backslash can never open a bogus span.
  const isValidEscape = (index: number): boolean =>
    css.charCodeAt(index) === 0x5c && !isNewline(css.charCodeAt(index + 1))

  function consumeEscape(index: number): number {
    let cursor = index + 1
    if (!isHex(css.charCodeAt(cursor))) return cursor < css.length ? cursor + 1 : cursor
    let digits = 0
    while (digits < 6 && isHex(css.charCodeAt(cursor))) {
      cursor += 1
      digits += 1
    }
    // One whitespace terminates a hex escape and belongs to it. That is precisely why
    // '\6b 100vh' is one identifier and not an identifier followed by a length.
    if (css.charCodeAt(cursor) === 0x0d && css.charCodeAt(cursor + 1) === 0x0a) return cursor + 2
    return isSpace(css.charCodeAt(cursor)) ? cursor + 1 : cursor
  }

  function consumeName(index: number): number {
    let cursor = index
    for (;;) {
      if (isName(css.charCodeAt(cursor))) cursor += 1
      else if (isValidEscape(cursor)) cursor = consumeEscape(cursor)
      else return cursor
    }
  }

  function startsName(index: number): boolean {
    const code = css.charCodeAt(index)
    if (isNameStart(code)) return true
    if (code === 0x2d) {
      const next = css.charCodeAt(index + 1)
      return isNameStart(next) || next === 0x2d || isValidEscape(index + 1)
    }
    return isValidEscape(index)
  }

  // The end of the number starting at this index, or -1 when none does.
  function numberEnd(index: number): number {
    CSS_NUMBER_RE.lastIndex = index
    return CSS_NUMBER_RE.exec(css) === null ? -1 : CSS_NUMBER_RE.lastIndex
  }

  function consumeString(index: number): number {
    const quote = css.charCodeAt(index)
    let cursor = index + 1
    for (;;) {
      if (cursor >= css.length) return cursor
      const code = css.charCodeAt(cursor)
      if (code === quote) return cursor + 1
      // A newline ends a bad string and stays outside it, which is how a browser
      // recovers the rest of the stylesheet.
      if (isNewline(code)) return cursor
      if (code !== 0x5c) {
        cursor += 1
      } else if (css.charCodeAt(cursor + 1) === 0x0d && css.charCodeAt(cursor + 2) === 0x0a) {
        cursor += 3
      } else if (isNewline(css.charCodeAt(cursor + 1))) {
        cursor += 2
      } else {
        cursor = consumeEscape(cursor)
      }
    }
  }

  // A url token's body ends at the first unescaped ')' or at EOF. Every bad-url
  // recovery the spec describes — an unexpected quote, '(' or whitespace before the
  // close — ends at exactly the same place, and the body is never interpreted here,
  // so one loop covers both and the span is identical either way.
  function consumeUrl(index: number): number {
    let cursor = index
    while (cursor < css.length) {
      if (css.charCodeAt(cursor) === 0x29) return cursor + 1
      cursor = isValidEscape(cursor) ? consumeEscape(cursor) : cursor + 1
    }
    return cursor
  }

  // Decoded identifier text. Needed wherever a name is compared rather than copied:
  // 'url', an at-rule name, a dimension's unit, and the leading '--' of a custom property.
  function decodeName(start: number, end: number): string {
    let value = ''
    let cursor = start
    while (cursor < end) {
      if (!isValidEscape(cursor)) {
        value += css[cursor]
        cursor += 1
        continue
      }
      const next = consumeEscape(cursor)
      let hexEnd = cursor + 1
      while (hexEnd < next && isHex(css.charCodeAt(hexEnd))) hexEnd += 1
      if (hexEnd > cursor + 1) {
        const code = parseInt(css.slice(cursor + 1, hexEnd), 16)
        value += code === 0 || code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)
          ? '\uFFFD'
          : String.fromCodePoint(code)
      } else {
        value += css.slice(cursor + 1, next) || '\uFFFD'
      }
      cursor = next
    }
    return value
  }

  function next(): void {
    token.start = pos
    token.split = pos
    if (pos >= css.length) {
      token.type = T_EOF
      token.end = pos
      return
    }
    const code = css.charCodeAt(pos)
    // A digit, '+', '-' or '.' are the only starts of a number, and each of the last
    // three can equally begin something else, so the grammar decides.
    const digitsEnd = isDigit(code) || code === 0x2b || code === 0x2d || code === 0x2e
      ? numberEnd(pos)
      : -1
    let type = T_OTHER
    if (isSpace(code)) {
      while (isSpace(css.charCodeAt(pos))) pos += 1
      type = T_TRIVIA
    } else if (code === 0x2f && css.charCodeAt(pos + 1) === 0x2a) {
      const close = css.indexOf('*/', pos + 2)
      pos = close === -1 ? css.length : close + 2
      type = T_TRIVIA
    } else if (code === 0x22 || code === 0x27) {
      pos = consumeString(pos)
    } else if (code === 0x3c && css.startsWith('<!--', pos)) {
      pos += 4
      type = T_TRIVIA
    } else if (code === 0x2d && css.startsWith('-->', pos)) {
      pos += 3
      type = T_TRIVIA
    } else if (code === 0x40 && startsName(pos + 1)) {
      token.split = pos + 1
      pos = consumeName(pos + 1)
      type = T_AT_KEYWORD
    } else if (code === 0x23 && (isName(css.charCodeAt(pos + 1)) || isValidEscape(pos + 1))) {
      // A hash token swallows its whole name, so an id selector such as '#h-100vh'
      // never leaves a bare dimension behind.
      pos = consumeName(pos + 1)
    } else if (digitsEnd !== -1) {
      if (startsName(digitsEnd)) {
        token.split = digitsEnd
        pos = consumeName(digitsEnd)
        type = T_DIMENSION
      } else {
        pos = css.charCodeAt(digitsEnd) === 0x25 ? digitsEnd + 1 : digitsEnd
      }
    } else if (startsName(pos)) {
      const nameEnd = consumeName(pos)
      if (css.charCodeAt(nameEnd) !== 0x28) {
        pos = nameEnd
        type = T_IDENT
      } else {
        // url() takes a raw body only when it is unquoted; quoted, it is an ordinary
        // function whose argument is a string token. Either way this opens a paren.
        let ahead = nameEnd + 1
        while (isSpace(css.charCodeAt(ahead))) ahead += 1
        const raw = css.charCodeAt(ahead) !== 0x22 && css.charCodeAt(ahead) !== 0x27
          && decodeName(pos, nameEnd).toLowerCase() === 'url'
        pos = raw ? consumeUrl(nameEnd + 1) : nameEnd + 1
        type = raw ? T_OTHER : T_OPEN_PAREN
      }
    } else {
      pos += 1
      type = code === 0x28 ? T_OPEN_PAREN
        : code === 0x29 ? T_CLOSE_PAREN
          : code === 0x5b ? T_OPEN_SQUARE
            : code === 0x5d ? T_CLOSE_SQUARE
              : code === 0x7b ? T_OPEN_CURLY
                : code === 0x7d ? T_CLOSE_CURLY
                  : code === 0x3a ? T_COLON
                    : code === 0x3b ? T_SEMICOLON
                      : T_OTHER
    }
    token.type = type
    token.end = pos
  }

  return {
    token,
    next,
    decodeName,
    restore: (saved: number): void => {
      pos = saved
    },
  }
}

/**
 * Rewrite viewport units in DECLARATION VALUES ONLY.
 *
 * Tailwind duplicates an arbitrary value into the escaped class selector
 * (.w-\[min\(78vw\,30rem\)\] { width: min(78vw,30rem) }), so rewriting the whole
 * stylesheet injects raw ( ) * into the selector, the selector becomes invalid, and the
 * browser drops the entire rule — the declaration with it. At-rule preludes are just as
 * unsafe, since var() is not legal in a media query condition.
 *
 * Structure is read from the token stream, following css-syntax-3 §5:
 *   - a stylesheet holds only at-rules and qualified rules, so a top-level statement is
 *     never a declaration — '--foo:hover, .w-\[50vw\]' is a selector list;
 *   - inside a block, a statement is a declaration only as '<ident> :', and for a
 *     non-custom property only while its value has no top-level '{}' block, which is
 *     what separates 'color: red' from a nested 'div:hover { … }';
 *   - '(', '[' and a function's '(' open simple blocks, so ';' and '{' inside them are
 *     component values: '@container style(--x: fn({a:b} 50vh;))' is one prelude;
 *   - '@property' descriptors reject var(), so a rewrite there would drop the whole
 *     registration.
 */
function transformViewportUnits(css: string): string {
  const { token, next, decodeName, restore } = createCssTokenizer(css)
  const rewrites: { start: number; end: number; text: string }[] = []
  const blocks: CssBlock[] = []
  let mode = MODE_STATEMENT
  let skipRewrites = false
  let pendingAtName = ''
  // Where this statement's rewrites begin, while it is still only assumed to be a
  // declaration. A top-level '{' proves it was a qualified rule, and the rewrites made
  // in what is really its prelude are dropped. -1 once the statement is settled.
  let speculativeFrom = -1

  function rewriteDimension(): void {
    const raw = css.slice(token.split, token.end)
    const unit = raw.includes('\\') ? decodeName(token.split, token.end) : raw
    const canonical = unit.toLowerCase()
    if (!VIEWPORT_UNITS.has(canonical)) return
    const amount = css.slice(token.start, token.split)
    const num = parseFloat(amount)
    if (!Number.isFinite(num)) return
    const isWidth = canonical.endsWith('w')
    const varName = isWidth ? '--mercury-vw' : '--mercury-vh'
    const text = num === 100
      ? `calc(100 * var(${varName}, 1${unit}))`
      : num === 1
        ? `var(${varName}, 1${unit})`
        : `calc(${amount} * var(${varName}, 1${unit}))`
    rewrites.push({ start: token.start, end: token.end, text })
  }

  // 'consume a declaration' needs '<ident> <whitespace>* :'. The colon is consumed on a
  // match; otherwise the lookahead is rolled back so the token stays in the prelude.
  function startsDeclaration(): boolean {
    const nameStart = token.start
    const nameEnd = token.end
    do next()
    while (token.type === T_TRIVIA)
    if (token.type !== T_COLON) {
      // Not a declaration after all, so the lookahead belongs to a prelude: rewind to
      // just after the identifier and let the main loop read it again.
      restore(nameEnd)
      return false
    }
    const raw = css.slice(nameStart, nameEnd)
    // Bounded to the name: an unbounded search would rescan the rest of the stylesheet
    // for every declaration, which is quadratic on CSS that carries no escape at all.
    const name = raw.includes('\\') ? decodeName(nameStart, nameEnd) : raw
    // Only a custom property may take a block as its value, so only it is settled here.
    speculativeFrom = name.startsWith('--') ? -1 : rewrites.length
    return true
  }

  for (;;) {
    next()
    const type = token.type
    if (type === T_EOF) break

    if (type === T_DIMENSION) {
      if (mode === MODE_VALUE && !skipRewrites) rewriteDimension()
      continue
    }
    if (type === T_OPEN_PAREN || type === T_OPEN_SQUARE) {
      blocks.push({
        closer: type === T_OPEN_SQUARE ? T_CLOSE_SQUARE : T_CLOSE_PAREN,
        rule: false,
        outerSkip: skipRewrites,
      })
      continue
    }
    if (type === T_CLOSE_PAREN || type === T_CLOSE_SQUARE || type === T_CLOSE_CURLY) {
      const block = blocks[blocks.length - 1]
      if (!block || block.closer !== type) continue
      blocks.pop()
      if (!block.rule) continue
      mode = MODE_STATEMENT
      skipRewrites = block.outerSkip
      pendingAtName = ''
      speculativeFrom = -1
      continue
    }
    // Inside '(', '[' or a value's own '{}' block there is no structure to read: the
    // enclosing statement's mode already decides what those tokens are. A nested '{'
    // still has to be pushed, or its '}' would close the enclosing rule early and the
    // declarations after it would be read as selector text.
    const enclosing = blocks[blocks.length - 1]
    if (enclosing !== undefined && !enclosing.rule) {
      if (type === T_OPEN_CURLY) {
        blocks.push({ closer: T_CLOSE_CURLY, rule: false, outerSkip: skipRewrites })
      }
      continue
    }

    if (type === T_OPEN_CURLY) {
      if (mode === MODE_VALUE && speculativeFrom >= 0) {
        // A top-level block in a non-custom property's value means this was never a
        // declaration, so everything rewritten so far was really selector text.
        rewrites.length = speculativeFrom
        mode = MODE_PRELUDE
      }
      const rule = mode !== MODE_VALUE
      blocks.push({ closer: T_CLOSE_CURLY, rule, outerSkip: skipRewrites })
      if (rule) {
        if (pendingAtName === 'property') skipRewrites = true
        mode = MODE_STATEMENT
      }
      pendingAtName = ''
      speculativeFrom = -1
      continue
    }
    if (type === T_SEMICOLON) {
      mode = MODE_STATEMENT
      pendingAtName = ''
      speculativeFrom = -1
      continue
    }
    if (mode !== MODE_STATEMENT || type === T_TRIVIA) continue

    if (type === T_AT_KEYWORD) {
      pendingAtName = decodeName(token.split, token.end).toLowerCase()
      mode = MODE_PRELUDE
    } else if (blocks.length === 0 || type !== T_IDENT) {
      mode = MODE_PRELUDE
    } else {
      mode = startsDeclaration() ? MODE_VALUE : MODE_PRELUDE
    }
  }

  if (rewrites.length === 0) return css
  let out = ''
  let cursor = 0
  for (const rewrite of rewrites) {
    out += css.slice(cursor, rewrite.start) + rewrite.text
    cursor = rewrite.end
  }
  return out + css.slice(cursor)
}

export default function mercuryViewportPlugin() {
  let server: MercuryViteServer | null = null
  // Deliberately no 'enforce'. 'vite:css-post' is the last plugin to touch CSS and what
  // it hands on differs by mode: in serve it wraps the stylesheet into a JS module
  // ('const __vite__css = "…"'), in build it empties the module and emits the asset
  // later. So transform() owns serve — and only serve, or the build asset would be
  // rewritten twice — while generateBundle() owns build. Declaring 'post' would hand
  // transform() that JS module, whose CSS is a string literal this rewriter must never
  // touch, and every live preview would silently stop being rewritten at all.
  let isBuild = false
  return {
    name: 'mercury-viewport-units',
    configResolved(config: { command?: string }) {
      isBuild = config.command === 'build'
    },
    configureServer(nextServer: MercuryViteServer) {
      server = nextServer
      const originalSend = nextServer.ws.send.bind(nextServer.ws) as MercuryViteWsSend
      rawViteWsSend = originalSend
      nextServer.ws.send = ((...args: [unknown] | [string, unknown]) => {
        if (args.length === 1) {
          const [payload] = args
          if (bufferCorrelatedFullReload(nextServer, payload)) return
          if (forwardCorrelatedVitePayload(nextServer, payload, originalSend)) return
          originalSend(payload)
          return
        }
        originalSend(args[0], args[1])
      }) as MercuryViteWsSend
      installEditHmrEndpoint(nextServer)
      installStampViteRefreshEndpoint(nextServer)
    },
    handleHotUpdate(context: { file: string }) {
      const file = normalizeEditHmrPath(context.file)
      if (!server) return
      // A stamp-refresh-originated change must never count toward edit-HMR
      // correlation. Consuming the marker leaves a later REAL edit of the same
      // file free to correlate normally.
      if (consumeStampRefreshPath(file)) return
      for (const [verificationId, transaction] of editHmrTransactions) {
        transaction.seenFiles.add(file)
        transaction.pendingUpdateFiles.add(file)
        if (transaction.quietTimer) {
          clearTimeout(transaction.quietTimer)
          transaction.quietTimer = null
        }
        maybePublishEditHmr(server, verificationId)
      }
    },
    transform(code: string, id: string) {
      if (isBuild) return
      if (!id.match(/\.css(\?.*)?$/)) return
      if (!VIEWPORT_UNIT_HINT_RE.test(code)) return
      return { code: transformViewportUnits(code), map: null }
    },
    generateBundle(_: unknown, bundle: Record<string, { type: string; source?: string | Uint8Array }>) {
      for (const [name, asset] of Object.entries(bundle)) {
        if (!name.endsWith('.css') || asset.type !== 'asset') continue
        if (typeof asset.source !== 'string') continue
        if (!VIEWPORT_UNIT_HINT_RE.test(asset.source)) continue
        asset.source = transformViewportUnits(asset.source)
      }
    },
  }
}
